def amicable_numbers_sum(n):
    def sieve(n):
        if n <= 0:
            return []
        n += 1
        sieve = [0] * n
        for i in range(1, n):
            if sieve[i] < i:
                for j in range(i * 2, n, i):
                    if sieve[j] == 0:
                        sieve[j] = i
        return [i for i in range(n) if i != 0 and sieve[i] != 0]

    def sum_of_divisors(n):
        result = 0
        i = 1
        while i * i <= n:
            if n % i == 0:
                result += i
                if n // i != i:
                    result += n // i
            i += 1
        return result

    def is_amicable(a, b):
        return sum_of_divisors(a) == b and sum_of_divisors(b) == a

    total = 0
    for i in range(1, n + 1):
        if is_amicable(i, sum_of_divisors(i)):
            total += i

    return total

